SELECT DATE_FORMAT(s.opened_date, 'yyyy-MM') opened_month, CASE WHEN s.sqft >= 16315 THEN 'high' WHEN s.sqft >= 8259 THEN 'mid' ELSE 'low' END sqft_bucket, COUNT(DISTINCT ss.units) unique_stores, MAX(ss.revenue) max_revenue FROM store_sales ss RIGHT OUTER JOIN stores s ON ss.store_id = s.id INNER JOIN products p ON p.id = ss.product_id GROUP BY DATE_FORMAT(s.opened_date, 'yyyy-MM'), CASE WHEN s.sqft >= 16315 THEN 'high' WHEN s.sqft >= 8259 THEN 'mid' ELSE 'low' END ORDER BY max_revenue DESC;
